#[cfg (not (target_os = "wasi"))] multi_threaded_rt_test ! { #[cfg (unix)] #[cfg_attr (miri , ignore)] #[test] fn unix_listener_bind () { let rt = rt () ; let _enter = rt . enter () ; let dir = tempfile :: tempdir () . unwrap () ; let path = dir . path () . join ("socket") ; let listener = net :: UnixListener :: bind (path) . unwrap () ; let _ : tokio :: time :: error :: Elapsed = Handle :: current () . block_on (tokio :: time :: timeout (Duration :: from_millis (10) , listener . accept () ,)) . unwrap_err () ;}
#[test] fn sleep () { let rt = rt () ; let _enter = rt . enter () ; Handle :: current () . block_on (time :: sleep (Duration :: from_millis (100))) ;}
#[test] #[should_panic (expected = "A Tokio 1.x context was found, but it is being shutdown.")] fn sleep_before_shutdown_panics () { let rt = rt () ; let _enter = rt . enter () ; let f = time :: sleep (Duration :: from_millis (100)) ; rt . shutdown_timeout (Duration :: from_secs (1000)) ; Handle :: current () . block_on (f) ;}
#[test] #[should_panic (expected = "A Tokio 1.x context was found, but it is being shutdown.")] fn sleep_after_shutdown_panics () { let rt = rt () ; let _enter = rt . enter () ; rt . shutdown_timeout (Duration :: from_secs (1000)) ; Handle :: current () . block_on (time :: sleep (Duration :: from_millis (100))) ;}
}